// IamServiceHandler is an implementation of the cloud.v1.api.IamService service.
type IamServiceHandler interface {
	// Register is public self-signup, gated by
	// PlatformSettings.allow_self_registration. Not idempotent: each call
	// creates a new account.
	Register(context.Context, *api.RegisterRequest) (*api.RegisterResponse, error)
	// Login authenticates by nickname|email + password and issues a TokenPair.
	// Not idempotent: each call mints a new session/TokenPair.
	Login(context.Context, *api.LoginRequest) (*api.LoginResponse, error)
	// Refresh rotates a refresh_token into a new TokenPair. Not idempotent: the
	// refresh_token is single-use; a replay fails.
	Refresh(context.Context, *api.RefreshRequest) (*api.RefreshResponse, error)
	// Logout revokes the refresh_token's server-side session. Idempotent:
	// revoking an already-revoked session is a no-op.
	Logout(context.Context, *api.LogoutRequest) (*api.LogoutResponse, error)
	// RequestPasswordReset starts the forgot-password flow (emails a token).
	// Public. Always succeeds (no account-existence leak).
	RequestPasswordReset(context.Context, *api.RequestPasswordResetRequest) (*api.RequestPasswordResetResponse, error)
	// ConfirmPasswordReset consumes the emailed token and sets a new password.
	// Public. Not idempotent: the token is single-use.
	ConfirmPasswordReset(context.Context, *api.ConfirmPasswordResetRequest) (*api.ConfirmPasswordResetResponse, error)
	// VerifyEmail consumes an emailed verification token. Public: the token is
	// the credential and the user may be logged out.
	VerifyEmail(context.Context, *api.VerifyEmailRequest) (*api.VerifyEmailResponse, error)
	// CreateAccount is the admin-only account path (the public path is
	// Register). Not idempotent: each call creates a new account.
	CreateAccount(context.Context, *api.CreateAccountRequest) (*api.CreateAccountResponse, error)
	// GetAccount fetches one account by id. The handler allows platform admins,
	// the account itself, or callers sharing a tenant with the target account.
	GetAccount(context.Context, *api.GetAccountRequest) (*api.GetAccountResponse, error)
	// GetMyAccount returns the caller's own profile — authenticated, no
	// permission (self-read).
	GetMyAccount(context.Context, *api.GetMyAccountRequest) (*api.GetMyAccountResponse, error)
	// ListAccounts lists accounts platform-wide. Read-only.
	ListAccounts(context.Context, *api.ListAccountsRequest) (*api.ListAccountsResponse, error)
	// UpdateAccount is idempotent: a wholesale field set converges on retry.
	// The handler allows platform admins or the account itself.
	UpdateAccount(context.Context, *api.UpdateAccountRequest) (*api.UpdateAccountResponse, error)
	// DeleteAccount is idempotent: deleting an absent account is a no-op.
	DeleteAccount(context.Context, *api.DeleteAccountRequest) (*api.DeleteAccountResponse, error)
	// ChangePassword is authenticated self-service (old + new). Not idempotent.
	ChangePassword(context.Context, *api.ChangePasswordRequest) (*api.ChangePasswordResponse, error)
	// ResetPassword is the admin override (sets a new password for any account).
	// Idempotent: setting the same password twice converges.
	ResetPassword(context.Context, *api.ResetPasswordRequest) (*api.ResetPasswordResponse, error)
	// ResendVerification re-sends the caller's own email verification token.
	// Authenticated.
	ResendVerification(context.Context, *api.ResendVerificationRequest) (*api.ResendVerificationResponse, error)
	// CreateTenant is gated by PlatformSettings.allow_member_tenant_creation.
	// Not idempotent: each call creates a new tenant.
	CreateTenant(context.Context, *api.CreateTenantRequest) (*api.CreateTenantResponse, error)
	// GetTenant fetches by id or slug; slug is the routing-resolve path. The
	// handler resolves the tenant first and then allows platform admins or
	// tenant members.
	GetTenant(context.Context, *api.GetTenantRequest) (*api.GetTenantResponse, error)
	// ListMyTenants returns the caller's tenants — authenticated, no permission.
	ListMyTenants(context.Context, *api.ListMyTenantsRequest) (*api.ListMyTenantsResponse, error)
	// UpdateTenant edits name/slug. Idempotent: a wholesale field set converges
	// on retry.
	UpdateTenant(context.Context, *api.UpdateTenantRequest) (*api.UpdateTenantResponse, error)
	// DeleteTenant removes a tenant. Idempotent: deleting an absent tenant is a
	// no-op.
	DeleteTenant(context.Context, *api.DeleteTenantRequest) (*api.DeleteTenantResponse, error)
	// TransferTenantOwnership reassigns the owner. Idempotent: transferring to
	// the current owner is a no-op.
	TransferTenantOwnership(context.Context, *api.TransferTenantOwnershipRequest) (*api.TransferTenantOwnershipResponse, error)
	// LeaveTenant drops the caller's own membership — authenticated, no
	// permission. Idempotent: leaving a tenant you are not in is a no-op.
	LeaveTenant(context.Context, *api.LeaveTenantRequest) (*api.LeaveTenantResponse, error)
	// CreateRole is not idempotent: each call creates a new role.
	CreateRole(context.Context, *api.CreateRoleRequest) (*api.CreateRoleResponse, error)
	// GetRole fetches one role by id. Read-only.
	GetRole(context.Context, *api.GetRoleRequest) (*api.GetRoleResponse, error)
	// ListRoles lists roles visible to the caller (tenant or platform scope).
	// Read-only.
	ListRoles(context.Context, *api.ListRolesRequest) (*api.ListRolesResponse, error)
	// UpdateRole is idempotent: permissions REPLACES wholesale, converging on retry.
	UpdateRole(context.Context, *api.UpdateRoleRequest) (*api.UpdateRoleResponse, error)
	// DeleteRole removes a custom role. Idempotent: deleting an absent role is a
	// no-op.
	DeleteRole(context.Context, *api.DeleteRoleRequest) (*api.DeleteRoleResponse, error)
	// CreateMembership is not idempotent: each call creates a new membership row.
	CreateMembership(context.Context, *api.CreateMembershipRequest) (*api.CreateMembershipResponse, error)
	// GetMembership fetches one membership by id. Read-only.
	GetMembership(context.Context, *api.GetMembershipRequest) (*api.GetMembershipResponse, error)
	// ListMemberships lists one tenant's members. Read-only.
	ListMemberships(context.Context, *api.ListMembershipsRequest) (*api.ListMembershipsResponse, error)
	// UpdateMembership is idempotent: role_ids REPLACES wholesale, converging on retry.
	UpdateMembership(context.Context, *api.UpdateMembershipRequest) (*api.UpdateMembershipResponse, error)
	// DeleteMembership removes a member from a tenant (revokes access).
	// Idempotent: removing an absent membership is a no-op.
	DeleteMembership(context.Context, *api.DeleteMembershipRequest) (*api.DeleteMembershipResponse, error)
	// GetMyPermissions resolves the caller's own permissions — authenticated, no permission.
	GetMyPermissions(context.Context, *api.GetMyPermissionsRequest) (*api.GetMyPermissionsResponse, error)
	// ListPermissions returns the grantable-permission catalog — authenticated, no permission.
	ListPermissions(context.Context, *api.ListPermissionsRequest) (*api.ListPermissionsResponse, error)
	// CreateIdentityProvider configures a new OIDC provider. Admin-only. Not
	// idempotent: each call creates a new provider.
	CreateIdentityProvider(context.Context, *api.CreateIdentityProviderRequest) (*api.CreateIdentityProviderResponse, error)
	// GetIdentityProvider fetches one provider by id. Admin-only, read-only.
	GetIdentityProvider(context.Context, *api.GetIdentityProviderRequest) (*api.GetIdentityProviderResponse, error)
	// UpdateIdentityProvider edits a provider (a present secret rotates it).
	// Admin-only. Idempotent: a wholesale field set converges on retry.
	UpdateIdentityProvider(context.Context, *api.UpdateIdentityProviderRequest) (*api.UpdateIdentityProviderResponse, error)
	// DeleteIdentityProvider removes a provider. Admin-only. Idempotent: deleting
	// an absent provider is a no-op.
	DeleteIdentityProvider(context.Context, *api.DeleteIdentityProviderRequest) (*api.DeleteIdentityProviderResponse, error)
	// ListIdentityProviders returns the login-page buttons. Public, read-only.
	ListIdentityProviders(context.Context, *api.ListIdentityProvidersRequest) (*api.ListIdentityProvidersResponse, error)
	// StartSSO returns the IdP authorize URL. Public. Not idempotent: each call
	// mints fresh state + PKCE stashed server-side.
	StartSSO(context.Context, *api.StartSSORequest) (*api.StartSSOResponse, error)
	// CompleteSSO is the OIDC callback. Public. Not idempotent: the code is
	// single-use and a replay fails.
	CompleteSSO(context.Context, *api.CompleteSSORequest) (*api.CompleteSSOResponse, error)
	// LinkExternalIdentity is admin-only (admin asserts the binding). Idempotent
	// on (provider, subject).
	LinkExternalIdentity(context.Context, *api.LinkExternalIdentityRequest) (*api.LinkExternalIdentityResponse, error)
	// UnlinkExternalIdentity is authenticated; the service enforces
	// account-owner-or-admin. Idempotent: unlinking an absent link is a no-op.
	UnlinkExternalIdentity(context.Context, *api.UnlinkExternalIdentityRequest) (*api.UnlinkExternalIdentityResponse, error)
	// ListExternalIdentities is authenticated; the service enforces
	// account-owner-or-admin (the "my linked logins" view).
	ListExternalIdentities(context.Context, *api.ListExternalIdentitiesRequest) (*api.ListExternalIdentitiesResponse, error)
	// CreateApiToken mints a programmatic credential; the service enforces
	// account-owner-or-admin and caps a SERVICE token to the owner's
	// permissions. Not idempotent: each call mints a new token + secret.
	CreateApiToken(context.Context, *api.CreateApiTokenRequest) (*api.CreateApiTokenResponse, error)
	// ListApiTokens lists an account's tokens (metadata only). Authenticated;
	// the service enforces account-owner-or-admin.
	ListApiTokens(context.Context, *api.ListApiTokensRequest) (*api.ListApiTokensResponse, error)
	// RevokeApiToken disables a token. Authenticated; the service enforces
	// account-owner-or-admin. Idempotent: revoking an absent/already-revoked
	// token is a no-op.
	RevokeApiToken(context.Context, *api.RevokeApiTokenRequest) (*api.RevokeApiTokenResponse, error)
}

